css:
@page {
    @bottom-right {
        content: "Page " counter(page) " of " counter(pages);
    }
}

.starting .startinghead {
    display: table-header-group;
}

.lastt {
    position: fixed;
    bottom: 0;
    width: 100%;
    z-index: -1;
}

#father {
    width: 100%;
    margin: 0 auto;
    font-size: 12px;
}

#center {

}

.headertable {
    height: 100%;
    font-size: 10px;
    color: black;
}

.headertable td, .headertable th {
    padding: 5px !important;
    border: none !important;
    border-top: none !important;
}

.lefttable td:nth-child(1), .lefttable th:nth-child(1) {
    text-align: left !important;
    font-weight: 700;
    color: black;
}

.lefttable td:nth-child(2), .lefttable th:nth-child(2) {
    text-align: center !important;
    color: black;
}

.lefttable td:nth-child(3), .lefttable th:nth-child(3) {
    text-align: right !important;
    font-weight: 700;
    color: black;
}

.notlefttable td:nth-child(1), .notlefttable th:nth-child(1) {
    text-align: left !important;
    font-weight: 700;
    color: black;
}

.notlefttable td:nth-child(2), .notlefttable th:nth-child(2) {
    text-align: center !important;
    color: black;
}

.notlefttable td:nth-child(3), .notlefttable th:nth-child(3) {
    text-align: right !important;
    font-weight: 700;
    color: black;
}

.headertable .lefttable {
    width: 100% !important;
    border: 1px solid black;
    height: 100%;
}

.headertable .notlefttable {
    width: 100% !important;
    border: 1px solid black;
    height: 100%;
}

.headertable .lefttable td {
    border-top: none !important;
}

.headertable .notlefttable td {
    border-top: none !important;
}

h2, h3, h4 {
    margin-top: 0px !important;
}

#containerForTwo {
    width: 100%;
    display: flex;
    justify-content: space-between;
    gap: 10px;
}

li {
    list-style: none;
    font-size: 13px;
    font-weight: 500;
    width: fit-content;
    position: relative;
}

.print-format .letter-head {
    margin-bottom: 0 !important;
}

#leftOne {
    width: 73%;
    border: 2px solid black;
    padding: 0 3px;
    display: flex;
    justify-content: space-between;
}

#rightOne {
    width: 25%;
    border: 2px solid black;
    padding: 0 3px;
    display: flex;
    justify-content: space-between;
}

#first {
    margin: 0;
    padding: 0;
    float: left;
}

#second {
    direction: rtl;
    margin: 0;
    padding: 0;
    float: right;
    display: flex;
    justify-content: flex-start;
    flex-direction: column;
}

.table-container {
    margin-top: 10px;
}

table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
}

th, td {
    padding: 5px;
    text-align: center;
}

#footer1-father {
    width: 100%;
    display: flex;
    justify-content: space-between;
    font-size: 10px;
    margin-top: 80px;
    border: 2px solid blue; /* Temporary border to check visibility */
    padding: 10px; /* Add padding to ensure content is visible */
    background-color: lightgray; /* Temporary background color */
}


#nums table {
    width: 98%;
    border-collapse: collapse;
    font-size: 12px;
    margin-top: 40%;
   margin-left: 10px;
}

#nums th, #nums td {
    padding: 5px;
    text-align: center;
    border: 1px solid #000; /* Add borders to cells */
}

#nums th {
    background-color: #f2f2f2; /* Light gray background for headers */
    font-weight: bold;
}

#nums td {
    background-color: #fff; /* White background for cells */
}

#rightFooter1 {
    display: flex;
    width: 55%;
    justify-content: space-between;
    font-size: 12px;
}

#leftFooter1 {
    display: flex;
    align-items: center;
}

#buttons {
    display: flex;
    justify-content: space-between;
    width: 100%;
    margin-top: 70px;
}

button {
    padding-right: 5px;
    width: auto;
    height: 30px;
    background-color: white;
    border: 1.5px solid black;
}

#leftOne li {
    font-size: 10px;
}

#rightOne li {
    font-size: 10px;
}

.hide-on-first-page {
    display: none;
}

@page :first {
    .hide-on-first-page {
        display: none;
    }
}
